function deployedKey(f: FunctionSpecEntry): 'yes' | 'no' | 'unknown' {
  const d = f.code?.deployed
  return d === true ? 'yes' : d === false ? 'no' : 'unknown'
}

function tagsOf(f: FunctionSpecEntry): string[] {
  return [
    ...f.fields.SIDE_EFFECTS.map((s) => `se:${s}`),
    `fail:${f.fields.ON_FAILURE}`,
    `probe:${f.fields.PROBE_RESULT}`,
    `deployed:${deployedKey(f)}`,
    `witness:${f.witness}`,
  ]
}

function shortDate(iso: string | null): string {
  return iso ? iso.replace('T', ' ').slice(0, 16) : '—'
}

const fmt = (n: number | null, unknown: string): string => (n === null ? unknown : String(n))

// ---------------------------------------------------------------------------
// Inline SVG infographics. No dependency; every number drawn is one the page
// received, and a missing number is drawn as "unknown", never as zero.
// ---------------------------------------------------------------------------

function HealthRing({ completed, failed, running, ui, offline }: { completed: number | null; failed: number | null; running: number | null; ui: Ui; offline: boolean }) {
  const r = 34
  const circ = 2 * Math.PI * r
  const total = (completed ?? 0) + (failed ?? 0)
  const known = !offline && (completed !== null || failed !== null)
  const okFrac = known && total > 0 ? (completed ?? 0) / total : 0
  const badFrac = known && total > 0 ? (failed ?? 0) / total : 0
  const pct = known && total > 0 ? Math.round(okFrac * 100) : null
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
      <svg width={92} height={92} viewBox="0 0 92 92" role="img" aria-label={ui.healthRing}>
        <circle cx={46} cy={46} r={r} fill="none" stroke={C.border} strokeWidth={9} />
        {known && total > 0 && (
          <>
            <circle cx={46} cy={46} r={r} fill="none" stroke={C.accent} strokeWidth={9} strokeDasharray={`${okFrac * circ} ${circ}`} transform="rotate(-90 46 46)" strokeLinecap="butt" />
            <circle cx={46} cy={46} r={r} fill="none" stroke={C.bad} strokeWidth={9} strokeDasharray={`${badFrac * circ} ${circ}`} strokeDashoffset={-okFrac * circ} transform="rotate(-90 46 46)" strokeLinecap="butt" />
          </>
        )}
        <text x={46} y={44} textAnchor="middle" fill={known ? C.text : C.muted} fontFamily={C.mono} fontSize={pct === null ? 9 : 16} fontWeight={700} data-lang-exempt="live">
          {pct === null ? '?' : `${pct}%`}
        </text>
        <text x={46} y={58} textAnchor="middle" fill={C.muted} fontFamily={C.mono} fontSize={8}>
          {known && total > 0 ? '24h' : ui.unknown}
        </text>
      </svg>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4, fontFamily: C.mono, fontSize: 11.5 }}>
        <span style={{ color: C.accent }}>
          ● {ui.completed} <b data-lang-exempt="live">{offline ? ui.unknown : fmt(completed, ui.unknown)}</b>
        </span>
        <span style={{ color: C.bad }}>
          ● {ui.failedRuns} <b data-lang-exempt="live">{offline ? ui.unknown : fmt(failed, ui.unknown)}</b>
        </span>
        <span style={{ color: C.blue }}>
          ● {ui.running} <b data-lang-exempt="live">{offline ? ui.unknown : fmt(running, ui.unknown)}</b>
        </span>
      </div>
    </div>
  )
}

function Bars7d({ rows, ui, selectedId, onPick }: { rows: { id: string; status: FunctionStatus | null }[]; ui: Ui; selectedId: string | null; onPick: (id: string) => void }) {
  const anyDaily = rows.some((r) => r.status?.daily7d && r.status.daily7d.length > 0)
  const max = Math.max(
    1,
    ...rows.map((r) => {
      const s = r.status
      if (!s) return 0
      if (anyDaily && s.daily7d) return Math.max(0, ...s.daily7d.map((d) => (d.completed ?? 0) + (d.failed ?? 0)))
      return (s.runs7d.completed ?? 0) + (s.runs7d.failed ?? 0)
    }),
  )
  const w = 120
  const h = 22
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      {!anyDaily && rows.some((r) => r.status) && <div style={{ fontSize: 10.5, color: C.muted, lineHeight: 1.4 }}>{ui.bars7dNoDaily}</div>}
      {rows.map((r) => {
        const s = r.status
        const known = s !== null && (s.runs7d.completed !== null || s.runs7d.failed !== null || (s.daily7d?.length ?? 0) > 0)
        const cells = anyDaily && s?.daily7d ? s.daily7d.slice(-7) : known && s ? [{ day: '7d', completed: s.runs7d.completed, failed: s.runs7d.failed }] : []
        const cw = cells.length ? w / cells.length : w
        const sel = r.id === selectedId
        return (
          <button
            key={r.id}
            onClick={() => onPick(r.id)}
            title={r.id}
            style={{ display: 'flex', alignItems: 'center', gap: 8, background: sel ? C.raised : 'transparent', border: 'none', padding: '1px 4px', borderRadius: 3, cursor: 'pointer', color: C.text, textAlign: 'left' }}
          >
            <span style={{ fontFamily: C.mono, fontSize: 10, color: sel ? C.golden : C.muted, width: 150, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} data-lang-exempt="live">
              {r.id}
            </span>
            <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} aria-hidden="true">
              <rect x={0} y={0} width={w} height={h} fill={C.panel} />
              {cells.length === 0 ? (
                <text x={w / 2} y={h / 2 + 3} textAnchor="middle" fill={C.muted} fontFamily={C.mono} fontSize={8}>
                  {ui.unknown}
                </text>
              ) : (
                cells.map((c, i) => {
                  const ok = c.completed ?? 0
                  const bad = c.failed ?? 0
                  const okH = (ok / max) * (h - 2)
                  const badH = (bad / max) * (h - 2)
                  const x = i * cw + 1
                  return (
                    <g key={i}>
                      <rect x={x} y={h - 1 - okH} width={Math.max(1, cw - 2)} height={okH} fill={C.accent} />
                      <rect x={x} y={h - 1 - okH - badH} width={Math.max(1, cw - 2)} height={badH} fill={C.bad} />
                    </g>
                  )
                })
              )}
            </svg>
            <span style={{ fontFamily: C.mono, fontSize: 10, color: C.muted, minWidth: 64 }} data-lang-exempt="live">
              {known && s ? `${fmt(s.runs7d.completed, '?')} / ${fmt(s.runs7d.failed, '?')}` : ui.unknown}
            </span>
          </button>
        )
      })}
    </div>
  )
}

function LastRunTimeline({ rows, ui, now, selectedId, onPick }: { rows: { id: string; status: FunctionStatus | null }[]; ui: Ui; now: number; selectedId: string | null; onPick: (id: string) => void }) {
  const span = 7 * 24 * 3600 * 1000
  const w = 520
  const h = 54
  type Dot = { id: string; x: number; color: string; st: string; ended: number }
  const dots: Dot[] = rows
    .map((r): Dot | null => {
      const ended = r.status?.lastRun?.endedAt ? Date.parse(r.status.lastRun.endedAt) : NaN
      if (!Number.isFinite(ended)) return null
      const age = now - ended
      const x = 16 + Math.max(0, Math.min(1, 1 - age / span)) * (w - 32)
      const st = (r.status?.lastRun?.status ?? '').toUpperCase()
      const color = st === 'COMPLETED' ? C.accent : st === 'FAILED' || st === 'CANCELLED' ? C.bad : st === 'RUNNING' ? C.blue : C.muted
      return { id: r.id, x, color, st, ended }
    })
    .filter((d) => d !== null)
    .sort((a, b) => a.x - b.x)
  if (dots.length === 0) return <div style={{ fontSize: 12, color: C.muted }}>{ui.timelineEmpty}</div>
  return (
    <svg width="100%" viewBox={`0 0 ${w} ${h}`} role="img" aria-label={ui.timeline} style={{ maxWidth: w }}>
      <line x1={16} y1={30} x2={w - 16} y2={30} stroke={C.border} strokeWidth={1} />
      {[7, 6, 5, 4, 3, 2, 1, 0].map((d) => {
        const x = 16 + (1 - d / 7) * (w - 32)
        return (
          <g key={d}>
            <line x1={x} y1={26} x2={x} y2={34} stroke={C.border} />
            <text x={x} y={48} textAnchor="middle" fill={C.muted} fontFamily={C.mono} fontSize={8}>
              {d === 0 ? ui.now : `-${d}${ui.daysAgo}`}
            </text>
          </g>
        )
      })}
      {dots.map((d, i) => (
        <g key={d.id} style={{ cursor: 'pointer' }} onClick={() => onPick(d.id)}>
          <title>{`${d.id} · ${d.st || ui.unknown} · ${shortDate(new Date(d.ended).toISOString())}`}</title>
          <circle cx={d.x} cy={30 - ((i % 3) - 1) * 7} r={d.id === selectedId ? 5.5 : 4} fill={d.color} stroke={d.id === selectedId ? C.golden : C.bg} strokeWidth={1.5} />
        </g>
      ))}
    </svg>
  )
}

